                        beneficio: ds.beneficioHistory[q], cubiertos: ds.cubiertosHistory[q], hard: rs.m.hard };
            var score = this._composite(state);
            ds.performance = { overallScore: score };
            out.overallScore = score;
            out.score = score;
            out.roundScore = rs.score;
            out.ventas = ds.last.ventas;
            out.coste = ds.last.coste;
            out.margen = ds.last.margen;
            out.beneficio = ds.last.beneficio;
            out.cubiertos = ds.last.cubiertos;
            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _get(obj, key, dflt) {
            return Object.prototype.hasOwnProperty.call(obj, key) ? obj[key] : dflt;
        }

        _menu(a) {
            var es = this.ESC[a.escandallo1];
            var an = this.AN[a.analisis1];
            var ca = this.CARTA[a.carta2];
            var rule = a.precio2;
            var u = es[0], pf = es[1];
            var prom = an[0], pfac = an[1];
            var rem = ca[0], wf = ca[1], dc = ca[2];
            var i;
            if (rem === null) {
                rem = [];
                for (i = 0; i < this.DISHES.length; i++) {
                    var dd = this.DISHES[i];
                    if (dd[2] * (1.0 - u) / dd[1] > 0.35) { rem.push(dd[0]); }
                }
            }
            var out = [];
            for (i = 0; i < this.DISHES.length; i++) {
                var d = this.DISHES[i];
                var k = d[0], p = d[1], c = d[2], w = d[3], cl = d[4];
                if (rem.indexOf(k) >= 0) { continue; }
                var tc = (c + this._get(dc, k, 0.0)) * pf;
                var pc = c * (1.0 - u);
                var q;
                if (rule === 'margen') {
                    q = (cl === 'C') ? p + 1.0 : (cl === 'E') ? p * 1.03 : p;
                } else if (rule === 'multiplo') {
                    q = this._jsround(pc * 3.3 * 2.0) / 2.0;
                } else if (rule === 'subida') {
                    q = p * 1.10;
                } else {
                    q = p;
                }
                q = this._jsround(q * pfac * 2.0) / 2.0;
                out.push([k, q, tc, w * this._get(prom, k, 1.0) * this._get(wf, k, 1.0), p]);
            }
            return { base: out, rem: rem };
        }

        _event(dec, k) {
            var c = this.C;
            var self = this;
            var a = {};
            var j, i, p;
            for (j = 0; j < this.KEYS.length; j++) { a[this.KEYS[j]] = this._active(dec, k, this.KEYS[j]); }
            var mm = this._menu(a);
            var base = mm.base, rem = mm.rem;
            var lost = 0.0;
            for (i = 0; i < this.DISHES.length; i++) {
                var dd = this.DISHES[i];
                if (rem.indexOf(dd[0]) >= 0) { lost += dd[3] * this.LEAVE[dd[4]]; }
            }
            lost = lost / 100.0;
            var wsum = 0.0, over = 0.0, under = 0.0;
            for (i = 0; i < base.length; i++) { wsum += base[i][3]; }
            for (i = 0; i < base.length; i++) { over += base[i][3] * Math.max(0.0, base[i][1] / this.VALUE[base[i][0]] - 1.0); }
            over = over / wsum;
            for (i = 0; i < base.length; i++) { under += base[i][3] * Math.max(0.0, 1.0 - base[i][1] / this.VALUE[base[i][0]]); }
            under = under / wsum;
            var af = this.AFORO[a.aforo3], tu = this.TURN[a.turnos3], pr = this.PRES[a.presupuesto4], ve = this.VENTA[a.venta4];
            var covers = 0.0, sales = 0.0, food = 0.0, labour = 0.0, fixed = 0.0, mainsales = 0.0, maincost = 0.0;
            for (p = 0; p < 3; p++) {
                var cf = 1.0, lf = 1.0, sidef = 1.0, tfac = 1.0, pfac = 1.0, extra = 0.0, extrac = 0.0, share = 0.0, terr = 0.0;
                var wmul = {};
                var kk;
                if (p >= 1) { cf *= tu[0]; lf *= tu[1]; sidef *= tu[2]; }
                if (p === 1) { cf *= af[0]; terr = af[1]; }
                if (p === 2) {
                    tfac *= pr[0]; cf *= pr[1] * ve[1]; pfac *= pr[3];
                    for (kk in pr[2]) { if (Object.prototype.hasOwnProperty.call(pr[2], kk)) { wmul[kk] = this._get(wmul, kk, 1.0) * pr[2][kk]; } }
                    for (kk in ve[0]) { if (Object.prototype.hasOwnProperty.call(ve[0], kk)) { wmul[kk] = this._get(wmul, kk, 1.0) * ve[0][kk]; } }
                    extra = ve[2]; extrac = ve[3]; share = ve[4];
                }
                var att = [], tot = 0.0;
                for (i = 0; i < base.length; i++) {
                    var x = base[i][3] * this._get(wmul, base[i][0], 1.0) * Math.pow(base[i][1] / base[i][4], -c.ED);
                    att.push(x);
                }
                for (i = 0; i < att.length; i++) { tot += att[i]; }
                var avgp = 0.0, avgc = 0.0;
                for (i = 0; i < base.length; i++) { avgp += (att[i] / tot) * base[i][1]; }
                for (i = 0; i < base.length; i++) { avgc += (att[i] / tot) * base[i][2]; }
                avgc = avgc * tfac;
                var pm = 1.0 - c.EUP * over + c.EDN * under;
                var n = c.N0 * c.SH[p] * cf * pm * (1.0 - lost);
                var ms = n * avgp * pfac;
                var mc = n * avgc;
                var sl = ms + n * (c.SIDE * sidef * pfac + extra);
                var fd = mc + n * (c.SIDE_C * sidef * tfac + extrac);
                var lab = n * c.LV + c.LFIX * c.SH[p] * lf + terr + sl * share;
                var fx = c.FIX * c.SH[p] + c.DISH * base.length * c.SH[p];
                covers += n; sales += sl; food += fd; labour += lab; fixed += fx; mainsales += ms; maincost += mc;
            }
            var sysc = this.ESC[a.escandallo1][2] + this.AN[a.analisis1][2] + this.CARTA[a.carta2][3] + pr[4] + ve[5];
            var profit = sales - food - labour - fixed - sysc;
            var hard = 0;
            this.HARD.forEach(function(h2) { if (a[h2[0]] === h2[1] && k >= self.ROUND_OF[h2[0]]) { hard += 1; } });
            return { k: k, a: a, beneficio: profit, margen: (mainsales - maincost) / covers, ventas: sales, coste: 100.0 * food / sales,
                     covers: covers, food: food, labour: labour, fixed: fixed, sysc: sysc, rem: rem, hard: hard };
        }

        _components(r) {
            var c = this.C;
            return [this._clamp((r.beneficio - c.B_LO) / (c.B_HI - c.B_LO), 0, 1),
                    this._clamp((r.margen - c.M_LO) / (c.M_HI - c.M_LO), 0, 1),
                    this._clamp((r.ventas - c.V_LO) / (c.V_HI - c.V_LO), 0, 1)];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_B, c.W_M, c.W_V];
            var tw = 0, num = 0, i;
            for (i = 0; i < 3; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.ROUND_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'en') ? ',' : '.';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _r1(x) {
            return this._jsround(x * 10.0) / 10.0;
        }

        _r2(x) {
            return this._jsround(x * 100.0) / 100.0;
        }

        _fmtMin(n) {
            return this._fmtDec(n) + ' min';
        }

        _fmtMoney2(n) {
            var v = Math.round(n * 100);
            var neg = v < 0;
            v = Math.abs(v);
            var whole = Math.floor(v / 100);
            var cents = v - whole * 100;
            var cs = (cents < 10 ? '0' : '') + String(cents);
            var body = this._fmtInt(whole) + ((this._lang() === 'en') ? '.' : ',') + cs;
            if (this._lang() === 'en') { return (neg ? '-' : '') + '€' + body; }
            return (neg ? '-' : '') + body + ' €';
        }

        _fmtPct1(n) {
            return this._fmtDec(n) + ((this._lang() === 'en') ? '%' : ' %');
        }

        _fmtMoney(n) {
            var v = Math.round(n);
            var body = this._fmtInt(Math.abs(v));
            if (this._lang() === 'en') { return (v < 0 ? '-' : '') + '€' + body; }
            return (v < 0 ? '-' : '') + body + ' €';
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var vH = ds.ventasHistory || [];
            var cH = ds.costeHistory || [];
            var mH = ds.margenHistory || [];
            var bH = ds.beneficioHistory || [];
            var nH = ds.cubiertosHistory || [];
            var n = vH.length;
            this._set('ventasDisplay', n ? this._fmtMoney(vH[n - 1]) : '-');
            this._set('costeDisplay', n ? this._fmtPct1(cH[n - 1]) : '-');
            this._set('margenDisplay', n ? this._fmtMoney2(mH[n - 1]) : '-');
            this._set('beneficioDisplay', n ? this._fmtMoney(bH[n - 1]) : '-');
            this._set('cubiertosDisplay', n ? this._fmtInt(nH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var pfx = { escandallo1: 'es', analisis1: 'an', carta2: 'ca', precio2: 'pr', aforo3: 'af', turnos3: 'tu', presupuesto4: 'pp', venta4: 've' };
            var opts = {
                escandallo1: ['receta', 'antiguo', 'factura', 'ojo'],
                analisis1: ['matriz', 'ventas', 'coste', 'competencia'],
                carta2: ['ingenieria', 'mantener', 'recorte', 'quitar'],
                precio2: ['margen', 'mantener', 'multiplo', 'subida'],
                aforo3: ['mixta', 'cuatro', 'apretar', 'sin'],
                turnos3: ['contribucion', 'actual', 'siempre', 'mediodia'],
                presupuesto4: ['revision', 'ninguno', 'porcentaje', 'descuentos'],
                venta4: ['sugerir', 'nada', 'comision', 'pan']
            };
            var keys = {
                fb_es_receta: 1, fb_es_antiguo: 1, fb_es_factura: 1, fb_es_ojo: 1,
                fb_an_matriz: 1, fb_an_ventas: 1, fb_an_coste: 1, fb_an_competencia: 1,
                fb_ca_ingenieria: 1, fb_ca_mantener: 1, fb_ca_recorte: 1, fb_ca_quitar: 1,
                fb_pr_margen: 1, fb_pr_mantener: 1, fb_pr_multiplo: 1, fb_pr_subida: 1,
                fb_af_mixta: 1, fb_af_cuatro: 1, fb_af_apretar: 1, fb_af_sin: 1,
                fb_tu_contribucion: 1, fb_tu_actual: 1, fb_tu_siempre: 1, fb_tu_mediodia: 1,
                fb_pp_revision: 1, fb_pp_ninguno: 1, fb_pp_porcentaje: 1, fb_pp_descuentos: 1,
                fb_ve_sugerir: 1, fb_ve_nada: 1, fb_ve_comision: 1, fb_ve_pan: 1
            };
            if (!opts[g] || opts[g].indexOf(v) < 0) { return 'fb_next'; }
            var key = 'fb_' + pfx[g] + '_' + v;
            return keys[key] ? key : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._event(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

        getChartConfig() {
            return {
                beneficioChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Profit', data: [], borderColor: '#6b3a5c', backgroundColor: 'rgba(107,58,92,0.12)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true }
                },
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Round score', data: [], borderColor: '#6b3a5c', backgroundColor: 'rgba(107,58,92,0.35)', borderWidth: 1 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var beneficioHistory = ds.beneficioHistory || [];
            var scoreHistory = ds.scoreHistory || [];
            var self = this;
            var labels = beneficioHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); });
            return {
                beneficioChart: {
                    labels: labels,
                    datasets: [
                        { data: beneficioHistory.slice(), label: this._t('chart_beneficio') }
                    ]
                },
                scoreChart: {
                    labels: scoreHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); }),
                    datasets: [
                        { data: scoreHistory.slice(), label: this._t('chart_score') }
                    ]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            var money = function(v) { return self._fmtMoney(v); };
            var pct = function(v) { return self._fmtPct1(v); };
            var money2 = function(v) { return self._fmtMoney2(v); };
            var count = function(v) { return self._fmtInt(v); };
            return [
                { key: 'results.ventas', label: 'Food sales', i18nKey: 'col_ventas', formatter: money },
                { key: 'results.coste', label: 'Food cost', i18nKey: 'col_coste', formatter: pct },
                { key: 'results.margen', label: 'Contribution per main', i18nKey: 'col_margen', formatter: money2 },
                { key: 'results.beneficio', label: 'Profit', i18nKey: 'col_beneficio', formatter: money },
                { key: 'results.cubiertos', label: 'Covers', i18nKey: 'col_cubiertos', formatter: count },
                { key: 'results.roundScore', label: 'Round score', i18nKey: 'col_score' }
            ];
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var d = this._flat(state, mm);
            var m = this._event(d, mm);
            var kp = this._kpis(m);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
            if (m.hard > 0) { insights.push(this._t('cm_cap')); }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                ventas: kp.ventas,
                coste: kp.coste,
                margen: kp.margen,
                beneficio: kp.beneficio,
                cubiertos: kp.cubiertos,
                food: Math.round(m.food),
                labour: Math.round(m.labour),
                fixed: Math.round(m.fixed),
                systemCost: Math.round(m.sysc),
                hard: m.hard,
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ej2717-cm">'
                + '<div class="ej2717-cm-score">' + score + '<span class="ej2717-cm-max">/100</span></div>'
                + '<div class="ej2717-cm-verdict">' + (s.performanceLabel || '') + '</div>'
                + '<div class="ej2717-cm-kpis">'
                + '<div class="ej2717-cm-kpi">' + this._t('cm_kpi_beneficio') + ' <strong>' + this._fmtMoney(s.beneficio || 0) + '</strong></div>'
                + '<div class="ej2717-cm-kpi">' + this._t('cm_kpi_margen') + ' <strong>' + this._fmtMoney2(s.margen || 0) + '</strong></div>'
                + '<div class="ej2717-cm-kpi">' + this._t('cm_kpi_ventas') + ' <strong>' + this._fmtMoney(s.ventas || 0) + '</strong></div>'
                + '<div class="ej2717-cm-kpi">' + this._t('cm_kpi_coste') + ' <strong>' + this._fmtPct1(s.coste || 0) + '</strong></div>'
                + '<div class="ej2717-cm-kpi">' + this._t('cm_kpi_cubiertos') + ' <strong>' + this._fmtInt(s.cubiertos || 0) + '</strong></div>'
                + '</div>'
                + '<div class="ej2717-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ej2717-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getTranslations() {
            return {
        es: {
            aforo3_apretar: `Dieciocho mesas, seis sin licencia`,
            aforo3_cuatro: `Doce mesas de cuatro, como el año pasado`,
            aforo3_mixta: `Doce mesas de dos que se juntan`,
            aforo3_sin: `Sin terraza este verano`,
            analisis1_competencia: `Los precios del restaurante de enfrente`,
            analisis1_coste: `Porcentaje de coste de cada plato`,
            analisis1_matriz: `Matriz de ingeniería de menú`,
            analisis1_ventas: `Ranking de ventas, como ahora`,
            btn_next: `Enviar las decisiones de esta ronda`,
            carta2_ingenieria: `Rediseñada con la matriz de menú`,
            carta2_mantener: `La carta tal como está, sin cambios`,
            carta2_quitar: `Quitar los tres que menos se venden`,
            carta2_recorte: `Fuera los platos con más del 35 %`,
